// PUBLIC entry. `pkg.vulnerable` is this file's own SAFE callable, and the
// consumer never calls it.
var legacy = require("./legacy.js");

exports.vulnerable = function modernSafe(input) {
  return "expmainsafe-safe:" + input;
};

// Re-publishes legacy's dangerous callable under a DIFFERENT public name,
// so legacy.js is genuinely loaded and genuinely reachable -- but never as
// `pkg.vulnerable`.
exports.runLegacy = function runLegacy(input) {
  return legacy.vulnerable(input);
};
